#include <stdio.h>

#define MAX_N 100000

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    int dp[MAX_N + 1];
    dp[0] = 0;

    for (int i = 1; i <= n; i++) {
        dp[i] = MAX_N;
        int value = i;

        while (value > 0) {
            int digit = value % 10;
            value /= 10;

            if (digit > 0 && dp[i - digit] + 1 < dp[i]) {
                dp[i] = dp[i - digit] + 1;
            }
        }
    }

    printf("%d\n", dp[n]);
    return 0;
}
